import { test } from "node:test";
import assert from "node:assert/strict";
import { setImmediate as tick } from "node:timers/promises";
import { MemoryReplica } from "../src/replication/replica.ts";
import { QuorumError, QuorumStore } from "../src/replication/quorum.ts";
import { ConfigRegistry, FACTORY_CONFIG, type DeviceConfig } from "../src/devices/configRegistry.ts";

// Three replicas, W = 2, R = 2. `slow` is B's latency in event-loop turns.
function cluster(slow = 0) {
    const a = new MemoryReplica<DeviceConfig>("a");
    const b = new MemoryReplica<DeviceConfig>("b", slow);
    const c = new MemoryReplica<DeviceConfig>("c");
    let now = 1000;
    const store = new QuorumStore([a, b, c], { w: 2, r: 2, nodeId: "eu-1", clock: () => ++now });
    return { a, b, c, store, registry: new ConfigRegistry(store) };
}

const cfg = (firmware: string): DeviceConfig => ({ firmware, reportEverySec: 60 });
const settle = async () => {
    for (let i = 0; i < 10; i++) await tick();
};

test("a written value can be read back with one replica down", async () => {
    const { b, store } = cluster();
    await store.put("cfg:m1", cfg("2.0.0"));
    b.up = false;
    assert.deepEqual(await store.get("cfg:m1"), cfg("2.0.0"));
});

test("a write needs two acknowledgements", async () => {
    const { a, b, store } = cluster();
    a.up = false;
    await store.put("cfg:m1", cfg("2.0.0"));
    b.up = false;
    await assert.rejects(store.put("cfg:m1", cfg("2.1.0")), QuorumError);
});

test("a read returns the latest write even when a replica that missed it answers first", async () => {
    const { a, c, store } = cluster(3);
    await store.put("cfg:m1", cfg("2.0.0"));
    c.up = false; // c misses the next write
    await store.put("cfg:m1", cfg("2.1.0"));
    c.up = true;
    a.up = false; // now one of the two replicas that took the write goes down
    const got = await store.get("cfg:m1");
    console.log("read after a failed over:", got, "| replica c holds:", c.peek("cfg:m1")?.value);
    assert.deepEqual(got, cfg("2.1.0"));
});

test("with two replicas down a read fails instead of reporting the key as missing", async () => {
    const { a, b, store } = cluster();
    await store.put("cfg:m1", cfg("2.0.0"));
    a.up = false;
    b.up = false;
    await assert.rejects(store.get("cfg:m1"), QuorumError);
});

test("read repair brings a replica that missed a write up to date", async () => {
    const { a, b, c, store } = cluster(2);
    await store.put("cfg:m1", cfg("2.0.0"));
    c.up = false;
    await store.put("cfg:m1", cfg("2.1.0"));
    c.up = true;
    a.latency = 1;
    assert.deepEqual(await store.get("cfg:m1"), cfg("2.1.0"));
    await settle();
    assert.deepEqual([a, b, c].map((r) => r.peek("cfg:m1")?.value.firmware), ["2.1.0", "2.1.0", "2.1.0"]);
});

test("writes with the same timestamp from two coordinators settle on one value everywhere", async () => {
    const a = new MemoryReplica<DeviceConfig>("a");
    const b = new MemoryReplica<DeviceConfig>("b");
    const c = new MemoryReplica<DeviceConfig>("c");
    const eu = new QuorumStore([a, b, c], { w: 2, r: 2, nodeId: "eu-1", clock: () => 500 });
    const us = new QuorumStore([c, b, a], { w: 2, r: 2, nodeId: "us-1", clock: () => 500 });
    await us.put("cfg:m1", cfg("from-us"));
    await eu.put("cfg:m1", cfg("from-eu"));
    await settle();
    assert.equal((await eu.get("cfg:m1"))?.firmware, "from-us");
    assert.deepEqual([a, b, c].map((r) => r.peek("cfg:m1")?.writer), ["us-1", "us-1", "us-1"]);
});

test("a meter keeps its rolled-out firmware when a replica fails over", async () => {
    const { a, c, registry } = cluster(3);
    c.up = false;
    assert.deepEqual(await registry.rollout(["m1", "m2"], "2.1.0"), { updated: ["m1", "m2"], failed: [] });
    c.up = true;
    a.up = false;
    assert.equal((await registry.desired("m1")).firmware, "2.1.0");
    assert.equal((await registry.desired("never-configured")).firmware, FACTORY_CONFIG.firmware);
});

test("during a two-replica outage meters are not told to go back to factory firmware", async () => {
    const { a, b, registry } = cluster();
    await registry.rollout(["m1"], "2.1.0");
    a.up = false;
    b.up = false;
    await assert.rejects(registry.desired("m1"), QuorumError);
    assert.deepEqual(await registry.rollout(["m1"], "2.2.0"), { updated: [], failed: ["m1"] });
});
